            minValue: 10,
            maxValue: 99,
            blockWidth: 50,
            margin: 10
        };

        // --- DOM Elements ---
        const container = document.getElementById('array-container');
        const ptrContainer = document.getElementById('pointers-container');
        const ptrI = document.getElementById('ptr-i');
        const ptrJ = document.getElementById('ptr-j');
        const msgBoard = document.getElementById('message-board');
