            State.isPlaying = false;
            State.isPaused = true;
            State.isFinished = false;
            State.currentStep = 0;
            State.queue = [];

            updateButtons();
            hidePointers();
            resetDecorations();

            // Generate Array
            State.size = Math.floor(Math.random() * (config.maxSize - config.minSize + 1)) + config.minSize;
            State.array = [];
            for (let i = 0; i < State.size; i++) {
