            }

            State.pivotIndex = State.size - 1; // Default

            renderInitialArray();
            updateContainerWidth();
            msgBoard.innerHTML = "Array initialized. Click 'Play' or pick a pivot.";
        }

        function updateContainerWidth() {
            const totalWidth = State.size * config.blockWidth + (State.size - 1) * config.margin;
            container.style.width = `${totalWidth}px`;
            ptrContainer.style.width = `${totalWidth}px`;
        }

        function getXPos(index) {
            return index * (config.blockWidth + config.margin);
        }

        function renderInitialArray() {
            container.innerHTML = '';
            container.appendChild(partLine);
            State.domNodes = [];

            State.array.forEach((val, idx) => {
                const block = document.createElement('div');
                block.className = 'block';
                block.innerText = val;
                block.style.transform = `translateX(${getXPos(idx)}px)`;

                // Allow user to select pivot before start
                block.addEventListener('click', () => {
                    if (State.currentStep === 0 && !State.isPlaying) {
                        selectUserPivot(idx);
                    }
                });

                container.appendChild(block);
                State.domNodes.push(block);
            });
        }

        function selectUserPivot(index) {
            if (index === State.size - 1) return; // Already last

            // Physically swap data
            let tempVal = State.array[index];
            State.array[index] = State.array[State.size - 1];
            State.array[State.size - 1] = tempVal;

            // Update DOM visual without animation for setup
            State.domNodes[index].innerText = State.array[index];
            State.domNodes[State.size - 1].innerText = State.array[State.size - 1];

            // Re-bind click event closure by re-rendering is safer, or just flash
            State.domNodes[State.size-1].classList.add('comparing');
