            msgBoard.innerHTML = `Pivot manually set to ${State.array[State.size - 1]}.`;
        }

        function resetDecorations() {
            partLine.style.opacity = '0';
            labelLeft.style.opacity = '0';
            labelRight.style.opacity = '0';
        }

        // --- Algorithm & Queue Generation ---
        function generateQueue() {
            State.queue = [];
            let arr = [...State.array];
            let pIdx = State.size - 1;
            let pivotVal = arr[pIdx];
            let i = -1;

            State.queue.push({ type: 'msg', text: `Starting Lomuto Partition. Pivot is ${pivotVal}.` });
