                State.queue.push({ type: 'compare', j: j, p: pIdx });

                if (arr[j] < pivotVal) {
                    i++;
                    State.queue.push({ type: 'move_i', idx: i });
                    State.queue.push({ type: 'msg', text: `${arr[j]} < ${pivotVal}. Increment i, swap arr[i] and arr[j].` });

                    if (i !== j) {
                        State.queue.push({ type: 'swap', i: i, j: j });
                        let temp = arr[i]; arr[i] = arr[j]; arr[j] = temp;
                    } else {
                        State.queue.push({ type: 'msg', text: `i and j are same (${i}), no physical swap needed.` });
                    }
                } else {
                    State.queue.push({ type: 'msg', text: `${arr[j]} &ge; ${pivotVal}. No action.` });
                }
                State.queue.push({ type: 'uncompare', j: j, p: pIdx });
            }

            i++;
            State.queue.push({ type: 'move_i', idx: i });
            State.queue.push({ type: 'msg', text: `Loop finished. Swap pivot into final correct position i (${i}).` });

            if (i !== pIdx) {
                State.queue.push({ type: 'swap', i: i, j: pIdx });
                let temp = arr[i]; arr[i] = arr[pIdx]; arr[pIdx] = temp;
            }

            State.queue.push({ type: 'done', pIdx: i });
        }


        // --- Animation Execution Engine ---

        const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

        function checkPause() {
            if (State.isPaused) {
                return new Promise(resolve => {
                    State.resolver = resolve;
                });
            }
            return Promise.resolve();
        }

        async function processStep(action) {

            // Adjust speed dynamically
            const duration = State.speed;
            document.documentElement.style.setProperty('--anim-speed', `${duration}ms`);

            switch(action.type) {
                case 'msg':
                    msgBoard.innerHTML = action.text;
                    break;

                case 'set_pivot':
                    State.domNodes[action.idx].classList.add('pivot');
                    break;

                case 'move_i':
                    ptrI.style.opacity = '1';
                    if (action.idx === -1) {
                        ptrI.style.transform = `translateX(-40px)`; // Off to the left
                    } else {
                        ptrI.style.transform = `translateX(${getXPos(action.idx) + 10}px)`; // Center slight offset
                    }
                    await sleep(duration * 0.8);
                    break;

                case 'move_j':
                    ptrJ.style.opacity = '1';
                    ptrJ.style.transform = `translateX(${getXPos(action.idx) + 10}px)`;
                    await sleep(duration * 0.8);
                    break;

                case 'compare':
                    State.domNodes[action.j].classList.add('comparing');
                    await sleep(duration);
                    break;

                case 'uncompare':
                    State.domNodes[action.j].classList.remove('comparing');
                    break;

                case 'swap':
                    const nodeI = State.domNodes[action.i];
                    const nodeJ = State.domNodes[action.j];

                    // Visual Swap
                    nodeI.style.transform = `translateX(${getXPos(action.j)}px)`;
                    nodeJ.style.transform = `translateX(${getXPos(action.i)}px)`;

                    // Logical DOM Array Swap
                    State.domNodes[action.i] = nodeJ;
                    State.domNodes[action.j] = nodeI;

                    await sleep(duration + 100);
                    break;

                case 'done':
                    State.domNodes[action.pIdx].classList.remove('pivot');
                    State.domNodes[action.pIdx].classList.add('comparing'); // Highlight final pos

                    // Draw partition line
                    const lineX = getXPos(action.pIdx) - config.margin/2;
                    partLine.style.transform = `translateX(${lineX}px)`;
                    partLine.style.opacity = '0.5';

                    // Colorize left and right
                    for(let k=0; k < State.size; k++) {
                        if (k < action.pIdx) State.domNodes[k].classList.add('smaller');
                        else if (k > action.pIdx) State.domNodes[k].classList.add('larger');
                    }

                    // Labels
                    labelLeft.style.opacity = '1';
                    labelRight.style.opacity = '1';

                    msgBoard.innerHTML = `Partition complete! Elements to left are < Pivot, right are &ge; Pivot.`;
                    hidePointers();
                    State.isFinished = true;
                    updateButtons();
                    break;
            }
        }

        function hidePointers() {
            ptrI.style.opacity = '0';
            ptrJ.style.opacity = '0';
        }

        async function runAnimationLoop() {
            while (State.currentStep < State.queue.length) {
                await checkPause();
                if (!State.isPlaying && !State.isFinished && State.isPaused) {
                    // Loop is paused but active
                } else if (!State.isPlaying && !State.isPaused) {
                     break; // Reset hit
                }

                if (State.isFinished) break;

                await processStep(State.queue[State.currentStep]);
                State.currentStep++;

                // If we were just stepping, pause again immediately
                if (!State.isPlaying) {
                     State.isPaused = true;
                     updateButtons();
                }
            }
            if(State.currentStep >= State.queue.length) {
                State.isPlaying = false;
                State.isPaused = true;
                updateButtons();
            }
        }

        // --- Controls ---

        function updateButtons() {
            btnPlay.disabled = State.isFinished;
            btnStep.disabled = State.isFinished || State.isPlaying;
            btnPlay.innerText = State.isPlaying ? "Pause" : (State.currentStep > 0 && !State.isFinished ? "Resume" : "Play");
        }

        btnPlay.addEventListener('click', () => {
            if (State.isFinished) return;

            if (State.currentStep === 0 && State.queue.length === 0) {
                generateQueue();
            }

            if (State.isPlaying) {
                // Pause
                State.isPlaying = false;
                State.isPaused = true;
            } else {
                // Play/Resume
                State.isPlaying = true;
                State.isPaused = false;
                if (State.resolver) {
                    State.resolver();
                    State.resolver = null;
                } else {
                    runAnimationLoop();
                }
            }
            updateButtons();
        });

        btnStep.addEventListener('click', () => {
            if (State.isFinished || State.isPlaying) return;

            if (State.currentStep === 0 && State.queue.length === 0) {
                generateQueue();
            }

            State.isPlaying = false; // Ensure loop doesn't free-run
            State.isPaused = false;  // Unblock wait

